#!/bin/sh
# Tests for bin/folder-atlas. Run from anywhere: sh test/test.sh
# Every concrete path on a page must look up to that page (test/cases.tsv, generated by scripts/sync.py),
# plus the cases below: inside a folder, ~, relative paths, project markers, names, JSON and exit codes.
# shellcheck disable=SC2088,SC2015 # a quoted ~ is the point of some cases; ok never fails

cd "$(dirname "$0")/.." || exit 2
ROOT=$(pwd)
ATLAS="$ROOT/bin/folder-atlas"
# Not $TMPDIR: on a Mac that is inside /var/folders, which is itself in the Atlas.
# Not /tmp: the Atlas has an entry for /private/tmp, which would match everything made here.
TMP=$(mktemp -d "$HOME/.atlas-test.XXXXXX") || exit 2
trap 'rm -rf "$TMP"' EXIT
export HOME=/Users/tester NO_COLOR=1
pass=0
fail=0

ok() { pass=$((pass + 1)); }
bad() { fail=$((fail + 1)); printf 'FAIL %s\n' "$*"; }

# field <json> <key>: the first string value of key in a JSON line
field() { printf '%s\n' "$1" | grep -o "\"$2\":\"[^\"]*\"" | head -1 | sed 's/^"[^"]*":"//; s/"$//'; }

# expect <expected id> <query> [<expected folder_verdict>]
expect() {
	out=$(cd "$TMP" && "$ATLAS" -j -- "$2" 2>&1)
	id=$(field "$out" id)
	if [ "$id" != "$1" ]; then bad "$2 → ${id:-nothing}, wanted $1"; return; fi
	if [ -n "$3" ] && [ "$(field "$out" folder_verdict)" != "$3" ]; then
		bad "$2 → verdict $(field "$out" folder_verdict), wanted $3"
		return
	fi
	ok
}
expect_none() {
	out=$(cd "$TMP" && "$ATLAS" -j -- "$1" 2>&1)
	case $out in *'"found":false'*) ok ;; *) bad "$1 should not be found: $(field "$out" id)" ;; esac
}

# 1. Every concrete path from the pages.
tab=$(printf '\t')
while IFS="$tab" read -r path id; do
	case $path in '#'* | '') continue ;; esac
	case $path in '~'*) path="$HOME${path#\~}" ;; esac
	expect "$id" "$path"
done <"$ROOT/test/cases.tsv"

# 2. Inside a known folder, the deepest folder wins.
expect library-caches "$HOME/Library/Caches/com.example.app/Cache.db"
expect spotify-cache "$HOME/Library/Caches/com.spotify.client/Data"
expect library-caches "$HOME/Library/Caches/com.apple.HomeKit" leave
expect safari-cache "$HOME/Library/Caches/com.apple.Safari" rebuilds
expect homebrew-cache "/opt/homebrew/Cellar/git/2.47.0" leave
expect homebrew-cache "$HOME/Library/Caches/Homebrew/downloads" rebuilds
expect docker-raw "$HOME/Library/Containers/com.docker.docker/Data/vms/0/data/Docker.raw"
expect containers "$HOME/Library/Containers/com.example.app"
expect node-modules "$HOME/code/app/node_modules/left-pad/node_modules"
expect node-modules "$HOME/Library/Mobile Documents/com~apple~CloudDocs/app/node_modules"

# 3. ~, relative paths and odd spellings of the same folder.
expect library-caches "~/Library/Caches"
expect library-caches "~/Library/../Library/Caches/"
expect library-caches "/System/Volumes/Data$HOME/Library/Caches"
expect library-caches "/Users/someone-else/Library/Caches"
expect var-folders "/var/folders/xy/abc123/T"
expect font-caches "/var/folders/xy/abc123/C/com.apple.FontRegistry"
expect quicklook-thumbnail-cache "/private/var/folders/xy/abc123/C/com.apple.QuickLook.thumbnailcache"
expect parallels-virtual-machines "/Users/Shared/Parallels/Windows 11.pvm"
expect deleted-users "/Users/Deleted Users/old.dmg"
expect trash "~/.Trash"
expect spotlight-index "/Volumes/Backup/.Spotlight-V100"
expect fseventsd "/Volumes/Backup/.fseventsd"
expect dot-trashes "/Volumes/Backup/.Trashes"
expect dot-underscore-files "/Volumes/Backup/Photos/._IMG_0001.jpg"
expect ds-store-files "$HOME/Desktop/project/.DS_Store"
expect macos-installers "/Applications/Install macOS Ventura.app"
expect final-cut-pro-render-files "/Volumes/Edit/Wedding.fcpbundle" leave
expect imovie-render-files "$HOME/Movies/iMovie Library.imovielibrary/Render Files" leave
expect photos-library "/Volumes/Photos/Photos Library.photoslibrary"
expect ios-device-support "$HOME/Library/Developer/Xcode/watchOS DeviceSupport/11.0"
expect pycache "$HOME/code/app/pkg/sub/__pycache__/mod.cpython-313.pyc"
expect yarn-cache "$HOME/code/app/.yarn/cache"
expect nextjs-cache "$HOME/code/site/.next/cache/images"
expect git-folder "$HOME/code/app/.git/objects"

# 4. Generic project folders need their marker file.
mkdir -p "$TMP/rs/target/debug" "$TMP/plain/target" "$TMP/fl/build" "$TMP/gr/build" "$TMP/py/venv" "$TMP/nv/venv" \
	"$TMP/sw/.build" "$TMP/ios/Pods"
: >"$TMP/rs/Cargo.toml"
: >"$TMP/fl/pubspec.yaml"
: >"$TMP/py/venv/pyvenv.cfg"
: >"$TMP/sw/Package.swift"
: >"$TMP/ios/Podfile"
expect rust-target-folder "$TMP/rs/target/debug"
expect_none "$TMP/plain/target"
expect dart-tool-and-flutter-build "$TMP/fl/build"
expect_none "$TMP/gr/build"
expect python-venv "$TMP/py/venv"
expect_none "$TMP/nv/venv"
expect swift-package-manager-cache "$TMP/sw/.build"
expect cocoapods-pods-folder "$TMP/ios/Pods"

# 5. Relative paths and bare names.
mkdir -p "$TMP/app/node_modules"
out=$(cd "$TMP/app" && "$ATLAS" -j node_modules)
[ "$(field "$out" id)" = node-modules ] && ok || bad "relative node_modules → $(field "$out" id)"
out=$(cd "$TMP/app" && "$ATLAS" -j ./node_modules/.bin)
[ "$(field "$out" id)" = node-modules ] && ok || bad "relative ./node_modules/.bin → $(field "$out" id)"
expect npm-cache npm
expect docker-raw docker
expect ds-store-files .DS_Store
n=$(cd "$TMP" && "$ATLAS" -j xcode | grep -c '"found":true')
[ "$n" -ge 2 ] && ok || bad "xcode should match several folders, got $n"
expect_none "/nonexistent/folder"
expect_none zzzz-no-such-thing

# 6. Output, options and exit codes.
"$ATLAS" "$HOME/Library/Caches" >/dev/null && ok || bad "found path should exit 0"
"$ATLAS" /nonexistent >/dev/null && bad "unknown path should exit 1" || ok
"$ATLAS" --bogus >/dev/null 2>&1
[ $? -eq 2 ] && ok || bad "unknown option should exit 2"
out=$("$ATLAS" "$HOME/Library/Caches")
case $out in *"https://siftmac.com/safe-to-delete/library-caches"*) ok ;; *) bad "short answer lacks the link: $out" ;; esac
out=$("$ATLAS" -m "$HOME/Library/Caches")
case $out in *"How to clear it"*"Sources"*) ok ;; *) bad "--more lacks its sections" ;; esac
case $out in *"$(printf '\033')"*) bad "colour with NO_COLOR set" ;; *) ok ;; esac
rows=$("$ATLAS" -l | grep -c '^  [A-Z]')
count=$(grep -c '"id": ' "$ROOT/atlas.json")
[ "$rows" -eq "$count" ] && ok || bad "--list shows $rows of $count folders"
"$ATLAS" -V | grep -q "^folder-atlas [0-9]" && ok || bad "--version"
lines=$("$ATLAS" "$HOME/Library/Caches" "$HOME/.npm" /nonexistent | wc -l | tr -d ' ')
[ "$lines" -eq 3 ] && ok || bad "three paths should give three lines, got $lines"
out=$(printf '%s\n' "$HOME/.npm" "$HOME/.Trash" | "$ATLAS" -j | grep -c '"found":true')
[ "$out" -eq 2 ] && ok || bad "paths on standard input"
out=$("$ATLAS" -mj "$HOME/.npm")
[ "$(field "$out" id)" = npm-cache ] && ok || bad "combined short options"

# 7. bin/folder-atlas is src/folder-atlas.sh plus the data (scripts/sync.py was run after the last edit).
code() { sed -e '/^data() {$/,$d' -e 's/^DATA_DATE=.*//' -e 's/^COUNT=.*//' "$1"; }
[ "$(code "$ROOT/src/folder-atlas.sh")" = "$(code "$ATLAS")" ] && ok || bad "bin/folder-atlas is out of date: run scripts/sync.py"

# 8. Every JSON line is valid JSON.
if command -v python3 >/dev/null 2>&1 && python3 -c 1 >/dev/null 2>&1; then
	(cd "$TMP" && "$ATLAS" -j "$HOME/Library/Caches" xcode /nonexistent "it's \"odd\"\\path" /opt/homebrew/Cellar) |
		python3 -c 'import json, sys; [json.loads(l) for l in sys.stdin]' && ok || bad "JSON lines don't parse"
	python3 -c 'import json, sys; d = json.load(open(sys.argv[1])); assert d["count"] == len(d["folders"])' \
		"$ROOT/atlas.json" && ok || bad "atlas.json"
fi

echo "$pass passed, $fail failed"
[ "$fail" -eq 0 ]
